from pathlib import Path
p=Path('cloudflare/millioner-api/src/index.js')
s=p.read_text(encoding='utf-8')

# constants
anchor="const WB_CONTENT_BASE = 'https://content-api.wildberries.ru';"
if "WB_FINANCE_BASE" not in s:
    s=s.replace(anchor,anchor+"\nconst WB_FINANCE_BASE = 'https://finance-api.wildberries.ru';\nconst WB_ADVERT_BASE = 'https://advert-api.wildberries.ru';\nconst WB_FINANCE_SYNC_MS = 6 * 60 * 60 * 1000;",1)

# schema
schema_anchor="    `CREATE TABLE IF NOT EXISTS sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,market TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,ok INTEGER NOT NULL DEFAULT 0,items INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '')`,"
extra="""\n    `CREATE TABLE IF NOT EXISTS wb_finance_rows (market TEXT NOT NULL,rrd_id TEXT NOT NULL,report_id TEXT NOT NULL DEFAULT '',rr_date INTEGER NOT NULL DEFAULT 0,vendor_code TEXT NOT NULL DEFAULT '',nm_id TEXT NOT NULL DEFAULT '',title TEXT NOT NULL DEFAULT '',doc_type TEXT NOT NULL DEFAULT '',operation TEXT NOT NULL DEFAULT '',qty REAL NOT NULL DEFAULT 0,retail_amount REAL NOT NULL DEFAULT 0,for_pay REAL NOT NULL DEFAULT 0,acquiring_fee REAL NOT NULL DEFAULT 0,delivery_service REAL NOT NULL DEFAULT 0,paid_storage REAL NOT NULL DEFAULT 0,paid_acceptance REAL NOT NULL DEFAULT 0,deduction REAL NOT NULL DEFAULT 0,penalty REAL NOT NULL DEFAULT 0,additional_payment REAL NOT NULL DEFAULT 0,rebill_logistic_cost REAL NOT NULL DEFAULT 0,raw_json TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(market,rrd_id))`,\n    `CREATE TABLE IF NOT EXISTS wb_ad_costs (market TEXT NOT NULL,day TEXT NOT NULL,advert_id TEXT NOT NULL,upd_num TEXT NOT NULL DEFAULT '',amount REAL NOT NULL DEFAULT 0,campaign TEXT NOT NULL DEFAULT '',payment_type TEXT NOT NULL DEFAULT '',raw_json TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(market,day,advert_id,upd_num))`,\n    `CREATE TABLE IF NOT EXISTS wb_finance_sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,market TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,ok INTEGER NOT NULL DEFAULT 0,finance_ok INTEGER NOT NULL DEFAULT 0,promotion_ok INTEGER NOT NULL DEFAULT 0,finance_items INTEGER NOT NULL DEFAULT 0,ad_items INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '')`,"""
if 'CREATE TABLE IF NOT EXISTS wb_finance_rows' not in s:
    if schema_anchor not in s: raise SystemExit('schema anchor missing')
    s=s.replace(schema_anchor,schema_anchor+extra,1)

idx_anchor="    `CREATE INDEX IF NOT EXISTS idx_sync_runs_market_started ON sync_runs(market,started_at DESC)`"
if 'idx_wb_finance_market_date' not in s:
    s=s.replace(idx_anchor,idx_anchor+",\n    `CREATE INDEX IF NOT EXISTS idx_wb_finance_market_date ON wb_finance_rows(market,rr_date DESC)`,\n    `CREATE INDEX IF NOT EXISTS idx_wb_ads_market_day ON wb_ad_costs(market,day DESC)`,\n    `CREATE INDEX IF NOT EXISTS idx_wb_finance_runs_market ON wb_finance_sync_runs(market,started_at DESC)`",1)

# summary/status routes
route_anchor="      if (url.pathname === '/api/orders' && request.method === 'GET') {"
routes="""      if (url.pathname === '/api/wb-finance-status' && request.method === 'GET') {\n        const market=normalizeMarket(url.searchParams.get('market'));\n        if(!['WB','WB2'].includes(market)) return json({ok:false,error:'market must be WB or WB2'},400,cors);\n        const latest=await env.DB.prepare('SELECT * FROM wb_finance_sync_runs WHERE market=? ORDER BY id DESC LIMIT 1').bind(market).first();\n        const f=await env.DB.prepare('SELECT COUNT(*) n,MAX(rr_date) lastDate FROM wb_finance_rows WHERE market=?').bind(market).first();\n        const a=await env.DB.prepare('SELECT COUNT(*) n,MAX(day) lastDay FROM wb_ad_costs WHERE market=?').bind(market).first();\n        return json({ok:true,market,latest:latest||null,financeRows:Number(f?.n||0),financeLastDate:Number(f?.lastDate||0)||null,adRows:Number(a?.n||0),adLastDay:a?.lastDay||null},200,cors);\n      }\n\n      if (url.pathname === '/api/wb-finance-summary' && request.method === 'GET') {\n        const market=normalizeMarket(url.searchParams.get('market'));\n        if(!['WB','WB2'].includes(market)) return json({ok:false,error:'market must be WB or WB2'},400,cors);\n        const days=Math.max(1,Math.min(3660,Number(url.searchParams.get('days')||30)));\n        const since=Date.now()-days*86400000;\n        const f=await env.DB.prepare(`SELECT SUM(retail_amount) retailAmount,SUM(for_pay) forPay,SUM(acquiring_fee) acquiring,SUM(delivery_service) delivery,SUM(paid_storage) storage,SUM(paid_acceptance) acceptance,SUM(deduction) deduction,SUM(penalty) penalty,SUM(additional_payment) additionalPayment,SUM(rebill_logistic_cost) rebill FROM wb_finance_rows WHERE market=? AND rr_date>=?`).bind(market,since).first();\n        const day=new Date(since).toISOString().slice(0,10);\n        const a=await env.DB.prepare('SELECT SUM(amount) amount FROM wb_ad_costs WHERE market=? AND day>=?').bind(market,day).first();\n        const n=x=>Number(x||0);\n        const expenses=n(f?.acquiring)+n(f?.delivery)+n(f?.storage)+n(f?.acceptance)+n(f?.deduction)+n(f?.penalty)+n(f?.rebill)+n(a?.amount);\n        return json({ok:true,market,days,retailAmount:n(f?.retailAmount),forPay:n(f?.forPay),acquiring:n(f?.acquiring),delivery:n(f?.delivery),storage:n(f?.storage),acceptance:n(f?.acceptance),deduction:n(f?.deduction),penalty:n(f?.penalty),additionalPayment:n(f?.additionalPayment),rebill:n(f?.rebill),advertising:n(a?.amount),expenses},200,cors);\n      }\n\n"""
if "'/api/wb-finance-status'" not in s:
    if route_anchor not in s: raise SystemExit('route anchor missing')
    s=s.replace(route_anchor,routes+route_anchor,1)

# scheduled finance sync after stock loop
old="""      for (const market of ['WB','WB2']) {\n        try { stocks[market] = await syncWbStockMarket(env, market, { force: false }); }\n        catch (e) { stocks[market] = { ok: false, error: String(e?.message || e) }; }\n      }\n      return { orders, stocks };"""
new="""      for (const market of ['WB','WB2']) {\n        try { stocks[market] = await syncWbStockMarket(env, market, { force: false }); }\n        catch (e) { stocks[market] = { ok: false, error: String(e?.message || e) }; }\n      }\n      const finance={};\n      for (const market of ['WB','WB2']) {\n        try { finance[market]=await syncWbFinance(env,market,{force:false}); }\n        catch(e){ finance[market]={ok:false,error:String(e?.message||e)}; }\n      }\n      return { orders, stocks, finance };"""
if 'finance[market]=await syncWbFinance' not in s:
    if old not in s: raise SystemExit('scheduled anchor missing')
    s=s.replace(old,new,1)

# append implementation before fetchWb
impl_anchor="async function fetchWb(env, market='WB') {"
impl=r'''function wbToken(env,market){return String((market==='WB2'?env.WB_TOKEN_2:env.WB_TOKEN)||'').trim()}
function wbMoney(v){const n=Number(v);return Number.isFinite(n)?n:0}
function wbDateMs(v){const t=Date.parse(String(v||''));return Number.isFinite(t)?t:0}
async function wbApiFetch(url,token,opts={}){const r=await fetch(url,{...opts,headers:{Accept:'application/json',Authorization:token,'Content-Type':'application/json',...(opts.headers||{})}});if(r.status===204)return [];let data=null;try{data=await r.json()}catch{}if(!r.ok){const e=new Error('WB API HTTP '+r.status+(data?.detail?' · '+data.detail:''));e.status=r.status;throw e}return data}
async function syncWbFinance(env,market='WB',{force=false}={}){if(!['WB','WB2'].includes(market))throw new Error('Unsupported WB finance market');const token=wbToken(env,market);if(!token)throw new Error((market==='WB2'?'WB_TOKEN_2':'WB_TOKEN')+' is not configured');const last=await env.DB.prepare('SELECT * FROM wb_finance_sync_runs WHERE market=? ORDER BY id DESC LIMIT 1').bind(market).first();if(!force&&last&&Date.now()-Number(last.started_at||0)<WB_FINANCE_SYNC_MS)return {ok:Boolean(last.ok),skipped:true,nextSyncAt:Number(last.started_at)+WB_FINANCE_SYNC_MS,financeOk:Boolean(last.finance_ok),promotionOk:Boolean(last.promotion_ok)};const now=Date.now(),run=await env.DB.prepare('INSERT INTO wb_finance_sync_runs(market,started_at) VALUES(?,?) RETURNING id').bind(market,now).first();let financeOk=false,promotionOk=false,financeItems=0,adItems=0,errors=[];const to=new Date(),from=new Date(Date.now()-30*86400000),fromDay=from.toISOString().slice(0,10),toDay=to.toISOString().slice(0,10);try{const rows=await wbApiFetch(WB_FINANCE_BASE+'/api/finance/v1/sales-reports/detailed',token,{method:'POST',body:JSON.stringify({dateFrom:fromDay,dateTo:toDay,limit:100000,rrdId:0,period:'daily'})});for(const x of(Array.isArray(rows)?rows:[])){const rrd=String(x.rrdId??'');if(!rrd)continue;await env.DB.prepare(`INSERT INTO wb_finance_rows(market,rrd_id,report_id,rr_date,vendor_code,nm_id,title,doc_type,operation,qty,retail_amount,for_pay,acquiring_fee,delivery_service,paid_storage,paid_acceptance,deduction,penalty,additional_payment,rebill_logistic_cost,raw_json,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(market,rrd_id) DO UPDATE SET report_id=excluded.report_id,rr_date=excluded.rr_date,vendor_code=excluded.vendor_code,nm_id=excluded.nm_id,title=excluded.title,doc_type=excluded.doc_type,operation=excluded.operation,qty=excluded.qty,retail_amount=excluded.retail_amount,for_pay=excluded.for_pay,acquiring_fee=excluded.acquiring_fee,delivery_service=excluded.delivery_service,paid_storage=excluded.paid_storage,paid_acceptance=excluded.paid_acceptance,deduction=excluded.deduction,penalty=excluded.penalty,additional_payment=excluded.additional_payment,rebill_logistic_cost=excluded.rebill_logistic_cost,raw_json=excluded.raw_json,updated_at=excluded.updated_at`).bind(market,rrd,String(x.reportId??''),wbDateMs(x.rrDate||x.saleDt||x.createDate),String(x.vendorCode??''),String(x.nmId??''),String(x.title??''),String(x.docTypeName??''),String(x.sellerOperName??''),wbMoney(x.quantity),wbMoney(x.retailAmount),wbMoney(x.forPay),wbMoney(x.acquiringFee),wbMoney(x.deliveryService),wbMoney(x.paidStorage),wbMoney(x.paidAcceptance),wbMoney(x.deduction),wbMoney(x.penalty),wbMoney(x.additionalPayment),wbMoney(x.rebillLogisticCost),JSON.stringify(x),now).run();financeItems++}financeOk=true}catch(e){errors.push('finance: '+String(e?.message||e))}try{const rows=await wbApiFetch(WB_ADVERT_BASE+'/adv/v1/upd?from='+encodeURIComponent(fromDay)+'&to='+encodeURIComponent(toDay),token);for(const x of(Array.isArray(rows)?rows:[])){const ts=String(x.updTime||''),day=(ts?ts.slice(0,10):toDay),advert=String(x.advertId??''),num=String(x.updNum??'');await env.DB.prepare(`INSERT INTO wb_ad_costs(market,day,advert_id,upd_num,amount,campaign,payment_type,raw_json,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(market,day,advert_id,upd_num) DO UPDATE SET amount=excluded.amount,campaign=excluded.campaign,payment_type=excluded.payment_type,raw_json=excluded.raw_json,updated_at=excluded.updated_at`).bind(market,day,advert,num,wbMoney(x.updSum),String(x.campName??''),String(x.paymentType??''),JSON.stringify(x),now).run();adItems++}promotionOk=true}catch(e){errors.push('promotion: '+String(e?.message||e))}const ok=financeOk||promotionOk;await env.DB.prepare('UPDATE wb_finance_sync_runs SET finished_at=?,ok=?,finance_ok=?,promotion_ok=?,finance_items=?,ad_items=?,error=? WHERE id=?').bind(Date.now(),ok?1:0,financeOk?1:0,promotionOk?1:0,financeItems,adItems,errors.join('; '),run.id).run();return {ok,market,financeOk,promotionOk,financeItems,adItems,error:errors.join('; ')}}

'''
if 'async function syncWbFinance' not in s:
    if impl_anchor not in s: raise SystemExit('impl anchor missing')
    s=s.replace(impl_anchor,impl+impl_anchor,1)

p.write_text(s,encoding='utf-8')
print('WB finance and ads sync installed')